WITH session_stats AS (SELECT session_id, SORT_ARRAY(COLLECT_SET(page)) page_list, MIN(duration_sec) min_duration_sec FROM web_events WHERE page IS NOT NULL GROUP BY session_id) SELECT sessions.country, session_stats.page_list, session_stats.min_duration_sec FROM sessions LEFT JOIN session_stats ON sessions.id = session_stats.session_id WHERE session_stats.min_duration_sec > 400 ORDER BY min_duration_sec DESC;
